from odoo import api, fields, models

# Letterhead modes, shared by letter.template / letter.document / res.company.
# `banner` and `classic` are generated by QWeb; `image`, `pdf_overlay` and
# `plain` use (or leave room for) the company's own letterhead.
LETTERHEAD_MODES = [
    ("banner", "Dark banner (generated)"),
    ("classic", "Understated classic (generated)"),
    ("image", "Uploaded image (PNG/JPG)"),
    ("pdf_overlay", "Uploaded PDF (overlay)"),
    ("plain", "No letterhead (pre-printed paper)"),
]

# Language families a template or text block is written in. A family, not a
# locale: the tenants run fr_CA, en_CA or en_US, often only one of them, so a
# template tied to "en_US" would vanish for an en_CA letter.
LETTER_LANGUAGES = [
    ("fr", "French"),
    ("en", "English"),
]

# Curated mail-merge token palette. Surfaced as a static legend in the
# template form view, and declared to `mail.render.mixin` by
# letter.document.mail_allowed_qweb_expressions(): Odoo renders only seven
# expressions for a user who is not a template editor, compared on the WHOLE
# string, so every token of this legend but the recipient name used to fail
# for an ordinary user. Bare paths only: `{{ object.x or "y" }}`
# matches no entry.
LETTER_MERGE_TOKENS = [
    ("{{ object.partner_id.name }}", "Recipient name"),
    ("{{ object.partner_id.parent_id.name }}", "Recipient organization"),
    ("{{ object.recipient_name }}", "Recipient name (frozen on the letter)"),
    ("{{ object.letter_date_display }}", "Letter date, written out in the letter's language"),
    ("{{ object.reference }}", "Letter reference (LET-YYYY-NNN)"),
    ("{{ object.company_id.name }}", "Sender name"),
    ("{{ object.signatory_id.name }}", "Signatory name"),
    ("{{ object.signatory_function }}", "Signatory title"),
]


class LetterTemplate(models.Model):
    _name = "letter.template"
    _description = "Letter template"
    _order = "name"

    name = fields.Char(string="Name", required=True)
    active = fields.Boolean(default=True)
    subject = fields.Char(
        string="Subject",
        help="Default letter title. Can contain merge fields.",
    )
    body_html = fields.Html(
        string="Body",
        # Nettoyé comme un modèle de courriel d'Odoo : les balises QWeb (<t t-out>)
        # et les styles restent, le script et les « on… » partent.
        sanitize="email_outgoing",
        help="Template body. Merge fields: {{ object.field }} or QWeb <t "
             "t-out=\"object.field\"/>.",
    )
    letterhead_style = fields.Selection(
        LETTERHEAD_MODES,
        string="Letterhead",
        default="banner",
        required=True,
    )
    note = fields.Text(string="Internal description")
    quicktext_ids = fields.Many2many(
        "letter.quicktext",
        string="Suggested text blocks",
    )
    language = fields.Selection(
        LETTER_LANGUAGES,
        string="Language",
        help="Language the template is written in. A letter only offers the "
             "templates of its own language, plus those left without one.",
    )
    code = fields.Char(
        string="Letter type",
        help="Shared by the versions of one letter in each language, so the "
             "bulk merge writes to each recipient in their own language.",
    )

    @api.model
    def _bf_language_of(self, lang):
        """Family of a locale code: "fr_CA" -> "fr". False when unknown."""
        family = (lang or "").split("_")[0]
        return family if family in dict(LETTER_LANGUAGES) else False

    def _bf_variant_for(self, lang):
        """The version of this letter written in ``lang``'s family.

        Falls back to the template itself when it has no letter type, is
        already in that language, or has no sibling in it."""
        self.ensure_one()
        family = self._bf_language_of(lang)
        if not self.code or not family or self.language in (False, family):
            return self
        siblings = self.search([("code", "=", self.code), ("language", "=", family)])
        if not siblings:
            return self
        # A tenant's duplicate keeps the letter type, so the bulk merge still
        # writes to each recipient in their language. Among the versions in
        # that language, the shipped one wins, then the oldest: never the
        # order of names.
        shipped = siblings._get_external_ids()
        return siblings.sorted(lambda t: (not shipped.get(t.id), t.id))[0]
